def chapter(index, section, dark=False):
    return f'<div class="chapter-label {"on-dark" if dark else ""}"><span>{index}</span><span>{section.upper()}</span></div>'

def arrow(href,label,css='text-link'):
    return f'<a class="{css}" href="{href}">{label}<span aria-hidden="true">↗</span></a>'

def cta(prefix, title="A new challenge worth discussing?", body="Bring a technical question, an institutional problem or a proposal. Good work begins with a clear conversation."):
    return f'''<section class="next-section"><div class="container next-inner" data-reveal><div><span class="eyebrow">A DIRECT LINE</span><h2>{title}</h2><p>{body}</p></div><a class="outline-button" href="{prefix}contact/">Get in touch <span>↗</span></a></div></section>'''

